      "返金ツールのJSON Schema定義内のdescriptionに「先に本人確認と注文確認が必須」と長文の制約事項を追記する手法。",
      "コード側の状態管理で前提条件完了を検証し、未完了時はツール実行を遮断するPrerequisite Gateを導入する手法。",
      "エージェントのサンプリングパラメータであるtemperatureを0.0に固定し、Few-shotに正しい返金手順の対話例を追加する手法。"
