    "explanation": "【公式アーキテクチャ解説】\n正解は「過去の完了済みツール呼び出しとその長大なJSON応答を簡潔な要約文に置換し、最新ターンのみ詳細を保持するコンパクション設計」です。\n\nマルチターンエージェントにおいて、すでに実行が完了した古いツールの「生JSONレスポンス（数十〜数百行）」をそのままコンテキストに保持し続けることはトークンの浪費であり、Lost in the Middleの原因になります。\nベストプラクティスは「Tool Result Compaction / Context Pruning」です。過去のツール結果（例: 注文履歴全件JSON）を「注文#12345: 配達完了（商品名: A、金額: 4,000円）」といった要約文に圧縮して会話履歴を再構築し、最新の作業に必要な情報のみを詳細に保持します。\n\n⚠️ 引っかけポイント: 単純に直近2往復以外を切り捨てる（FIFO）と、顧客の初期要望や本人確認完了の事実が消去されてしまい、エージェントが再度本人確認を要求する等の致命的なデグレを引き起こします。",
