      "各開発者のホームディレクトリ配下にある~/.claude/config.jsonに、各リポジトリ固有のテストコマンドを個別に記述する構成。",
      "リポジトリのルート直下にCLAUDE.mdファイルを配置し、ビルドやテストの規約を記載してGitでバージョン管理する構成。",
      "ソースコードの全ファイルの先頭行に、コメントアウト形式でCLAUDE_INSTRUCTIONタグを埋め込んで規約を記載する構成。"
