    "explanation": "【公式アーキテクチャ解説】\n正解は「リポジトリのルート直下にCLAUDE.mdファイルを配置し、ビルドやテストの規約を記載してGitでバージョン管理する構成」です。\n\nClaude Codeの設計における中核機能が `CLAUDE.md`（リポジトリ指示ファイル）です。\nリポジトリのルートディレクトリに `CLAUDE.md` を配置することで、Claude Codeがセッション開始時に自動的にこのファイルを読み込み、システム指示の一部としてコンテキストに取り込みます。これをGitでバージョン管理（コミット）することにより、50名のチーム全員が同一のビルドコマンド、テスト実行規約、コーディングスタイルを一元的に共有・強制できます。\n\n⚠️ 引っかけポイント: ホームディレクトリ配下の `~/.claude/` は開発者個人の環境設定用でありチーム共有に向かず、手動コピペや全ファイルへのコメント埋め込みは非効率かつメンテナンス不能です。",
    "officialRef": "Anthropic Certified Architect Guide: Scenario 2 - Code Generation / CLAUDE.md"
