      "最大反復回数（Max Turns）と全体タイムアウトを設定し、規定回数内に解決しない場合はループを中断して失敗ログを出す設計。",
      "テストが1回でも失敗した時点で修正ループを即座に破棄し、プロジェクト内の該当コードファイルを自動全削除する設計。",
      "テストフレームワークの全アサーションを自動的に「return true」に書き換え、テストが必ず即座にパスするように改変する設計。"
