    "question": "【シナリオ：Claude Code によるコード生成】\n前提: チームは数百万行に及ぶ巨大なモノレポ（Monorepo: バックエンド、フロントエンド、インフラコード、巨大なテストデータセットが同居）を管理している。\n\n状況・課題:\n開発者がフロントエンドの小さなUIコンポーネントの修正を Claude Code に指示したところ、エージェントがモノレポ内の巨大なテストデータ（数十万行のCSV/JSON）やバックエンドの無関係なファイルをコンテキストに読み込み始め、コンテキスト長の上限超過と莫大なトークン課金が発生した。\n\n問い:\nモノレポにおいて Claude Code の走査範囲を適切に制限し、コンテキスト汚染と無駄なコストを防止するための構成として、最も適切なものはどれか？",
