    "explanation": "【公式アーキテクチャ解説】\n正解は「.claudeignoreファイルを作成して不要ディレクトリを除外し、対象サブディレクトリに移動してClaude Codeを起動する構成」です。\n\nClaude Codeでは、Gitにおける `.gitignore` と同様に `.claudeignore` ファイルをサポートしています。\n巨大なテストデータセット（`fixtures/`）、ビルド成果物（`dist/`, `build/`）、無関係なサブプロジェクト（`packages/backend/`）などを `.claudeignore` に指定することで、ファイル検索ツール（Glob / Grep）の走査対象から完全に除外し、コンテキスト汚染と無駄なトークン消費を防止できます。また、作業対象のサブディレクトリ内で Claude Code を起動することも効果的です。\n\n⚠️ 引っかけポイント: リポジトリの物理的分割やファイルの物理削除は開発運用に莫大な破壊的影響を与え、極端なトークン絞り込みは作業自体を不可能にします。",
