    "question": "【シナリオ：Claude Code によるコード生成】\n前提: Claude Code はローカル環境でBashツールを使用してGitコマンドを自律的に発行できる。\n\n状況・課題:\nマージコンフリクトを解決しようとしたエージェントが、未コミットの重要ファイルが多数残っている作業ツリーに対して `git reset --hard HEAD` や `git checkout -f` を自律的に実行してしまい、開発者が数時間かけて書いたコードが完全に消失する重大インシデントが発生した。\n\n問い:\nこのような取り返しのつかない破壊的Gitコマンドの誤実行を防止し、開発者の作業資産を保護するためのアーキテクチャ対策として、最も適切なものはどれか？",
