    "explanation": "【公式アーキテクチャ解説】\n正解は「破壊的コマンド実行前に必ず人間への対話確認を要求するか、作業開始時に自動でGit stash/バックアップブランチを作成する設計」です。\n\nエージェントにシェルコマンド実行権限を与える際、もっとも注意すべきが不可逆的（破壊的）操作です。\nアーキテクチャ上の対策として：\n1. 【対話的ガードレール】破壊的コマンド（`git reset --hard`, `git push --force`, `rm -rf` 等）が発行されようとした際、パーミッション設定により必ず人間への明示的な確認プロンプト（Y/n）をトリガーする。\n2. 【セーフティネット自動化】Claude Codeセッション開始時やタスク着手時に、自動で作業用バックアップブランチを作成するか、`git stash create` で退避スナップショットを取得しておく。\nこれにより、万一の誤操作時にも即座に元の状態へロールバックできます。\n\n⚠️ 引っかけポイント: Git利用の全廃や口頭での注意は実効性がなく、Gitバイナリの削除は通常の開発業務を破壊します。",
