    "question": "【シナリオ：Claude Code によるコード生成】\n前提: 開発者が Claude Code CLI を起動し、半日にわたって複数機能の実装やリファクタリング、デバッグを同一セッション内で継続して作業している。\n\n状況・課題:\nセッションが長時間化するにつれて対話履歴が肥大化し、Claude Code の応答速度が目に見えて低下した。また、過去に試行錯誤した無関係なエラーログにモデルが引きずられ、新しいプロンプトに対する指示の正確性が劣化してきた。\n\n問い:\nセッションを終了して一からやり直すことなく、対話履歴をクリーンアップして応答速度と推論精度を回復させるための Claude Code の標準操作はどれか？",
