    "explanation": "【公式アーキテクチャ解説】\n正解は「/compact コマンドを実行して、これまでの作業履歴と決定事項を重要な要約に圧縮・集約する操作」です。\n\nClaude Code CLIには、対話履歴が長大化した際にコンテキストを整理するための専用スラッシュコマンド `/compact` が標準装備されています。\nこのコマンドを実行すると、これまでの試行錯誤（過去のツール呼び出し結果や長大なDiffなど）をClaude自身が「現在のタスク進捗と確定したコード変更点、未完了の課題」として簡潔に要約し、不要な生履歴をパージ（圧縮）します。これにより、コンテキストの消費量を大幅に削減し、高速かつクリアな推論状態を取り戻すことができます。\n\n⚠️ 引っかけポイント: PCの再起動や画面文字サイズの変更はコンテキスト長に何の影響も与えず、生履歴の手動削除はセッション構造を破損させます。",
