    "question": "【シナリオ：Claude Code によるコード生成】\n前提: 開発チームでは、「新機能追加時の定型プルリクエスト作成手順」や「セキュリティ監査レポートの定型出力」など、頻繁に行う複雑なワークフローが存在する。\n\n状況・課題:\nチームメンバーが各自で毎回長文のプロンプトを手入力しており、入力漏れや指示のブレによって生成されるPRやレポートのフォーマットが統一されない課題があった。\n\n問い:\nチーム固有の定型ワークフローをスクリプト化し、全メンバーが `/pr` や `/audit` といった短いコマンドで一貫して呼び出せるようにするための Claude Code の拡張機能はどれか？",
