    "explanation": "【公式アーキテクチャ解説】\n正解は「.claude/commands/ ディレクトリ配下にMarkdownプロンプトファイルを配置しカスタムスラッシュコマンドを定義する構成」です。\n\nClaude Codeは、プロジェクト固有の「カスタムスラッシュコマンド（Custom Slash Commands）」の作成をネイティブでサポートしています。\nリポジトリ内の `.claude/commands/` ディレクトリに、例えば `pr.md` や `audit.md` というMarkdownファイルを配置し、実行させたい指示や参照すべきドキュメントを定義しておくと、ユーザーがCLI上で `/pr` や `/audit` と入力するだけで、その構造化プロンプトが即座に展開・実行されます。これをGitリポジトリに含めることで、チーム全体で標準化されたワークフローを瞬時に共有できます。\n\n⚠️ 引っかけポイント: OSの辞書登録はバージョン管理できず、バイナリの独自フォークは今後の公式アップデートに追従できなくなります。",
    "officialRef": "Anthropic Certified Architect Guide: Custom Slash Commands in Claude Code"
