    "explanation": "【公式アーキテクチャ解説】\n正解は「まずGrepで対象関数名を正規表現検索して該当ファイルと行番号をピンポイントで絞り込み、その後必要な箇所のみFileReadする構成」です。\n\nClaude Codeにおけるコード探索ツールのベストプラクティスは「Filter then Read（絞り込んでから読む）」です。\n特定のシンボルや関数名を探す場合：\n1. まず `Grep` ツールを実行し、コードベース全体から該当シンボルが出現するファイルパスと行番号（例: `src/auth/crypto.ts:45`）を数ミリ秒・最小トークンで取得します。\n2. 絞り込まれた特定のファイルと対象行周辺のみを `FileRead`（`offset` や `limit` を指定）でピンポイントに読み込みます。\nこの2段階アプローチにより、全ファイル読込と比較して99%以上のトークンと時間を削減できます。\n\n⚠️ 引っかけポイント: 全ファイルの盲目的FileReadはトークン上限に直突し、事前学習データからの推測はリポジトリ固有の実装に対して確実にハルシネーションを起こします。",
