    "explanation": "【公式アーキテクチャ解説】\n正解は「最大対話往復数（例: 3ターン）を設定し、合意に至らない場合は未解決論点を明記して人間にエスカレーションする設計」です。\n\nマルチエージェントの相互作用（Peer-to-PeerやEvaluator-Optimizer）において最も一般的な落とし穴が「Ping-Pong Trap（無限議論）」です。\nモデル同士の価値基準や閾値のわずかなズレにより、終了条件を満たせないループが発生します。\nベストプラクティスは：\n1. 最大往復回数（Max Iterations: 2〜3回）のハードリミットをコード側で強制する。\n2. 規定回数内に意見が一致しない場合は、「見解が分かれている論点とその両論の根拠」をまとめた状態で人間（アナリスト）にエスカレーションし、最終判断を委ねる。\n\n⚠️ 引っかけポイント: ファクトチェックの無条件全肯定は検証機構そのものの無力化であり、プロセスの突然死や意図的遅延は解決になりません。",
