    "explanation": "【公式アーキテクチャ解説】\n正解は「読み取り専用データにはResources（URI経由の参照）を割り当て、状態変更アクションにはTools（関数実行）を割り当てる設計」です。\n\nMCP（Model Context Protocol）の3大プリミティブの役割分担：\n1. **Resources（リソース）**: `file://` や `postgres://tables/users` のようなURIで識別される「読み取り専用（Read-only）」のコンテキストデータ。ファイル内容やDBスキーマなど、取得してもシステム状態に副作用（Side-effect）を与えない静的・準静的データを提供します。\n2. **Tools（ツール）**: モデルが自律的に引数を渡して呼び出す「実行可能な関数」。APIリクエストの発行、DBのINSERT/UPDATE/DELETE、メール送信など、システム状態を変更したり動的な計算を行うアクションに割り当てます。\n3. **Prompts（プロンプト）**: ユーザーがスラッシュコマンド等で呼び出せる再利用可能なプロンプトテンプレート。\n\n⚠️ 引っかけポイント: GETリクエストやResource取得時の副作用（暗黙削除）はWebアーキテクチャ（REST/HTTP）の根本原則に反する危険な設計です。",
    "officialRef": "Anthropic Certified Architect Guide: MCP Primitives - Resources vs Tools vs Prompts"
