      "ClaudeのSystem Promptに「DROP TABLEやTRUNCATE TABLEは絶対に実行しないでください」と太字で書いておく設計。",
      "DB接続にSELECT権限のみを持つ読み取り専用ロールを用い、SQLパーサーでDDL/DMLの実行を物理遮断するガードレール設計。"
