    "explanation": "【公式アーキテクチャ解説】\n正解は「クライアントがprotocolVersionを含むinitializeを送り、サーバーがサポート能力を返した後にinitialized通知を送る手順」です。\n\nMCP（Model Context Protocol）の接続ライフサイクル仕様：\n1. **Initialize Phase**: クライアントがサーバーに対して `initialize` メソッド（クライアントのサポートする `protocolVersion`、クライアント情報、Capabilities）を送信。\n2. **Server Response**: サーバーは自身が合意した `protocolVersion`、サーバー情報、Capabilities（tools, resources, prompts等）を返却。\n3. **Initialized Notification**: クライアントが `notifications/initialized` を送信することでハンドシェイクが正式に完了。\nこの手順が正常に完了して初めて、`tools/list` や `resources/list` などのリクエスト発行が可能になります。\n\n⚠️ 引っかけポイント: 初期化前にいきなりツール呼び出しを行うことはプロトコル違反であり、秘密鍵の平文送信やPing爆撃は論外です。",
