      "参照頻度の高いドキュメントの文章をすべてBase64エンコードし、通信ペイロードのファイルサイズを圧縮して高速化する設計。",
      "MCPリソースの内容をシステムプロンプトの固定位置に配置し、ClaudeのPrompt Caching（ephemeralキャッシュ）を適用する設計。"
