      "開発者が毎日退勤する前に、その日の全対話ログを紙にプリンターで印刷し、翌朝手動でOCRスキャンして読み取らせる設計。",
      "セッションIDごとにメッセージ履歴、ツール実行状態、作業チェックリストをローカルストレージへJSON保存・復元する設計。"
