    "explanation": "【公式アーキテクチャ解説】\n正解は「-p（または --print）オプションを使用してプロンプトを渡し、処理結果を標準出力に出力させてプロセスを正常終了させる構成」です。\n\nClaude Code CLIをCI/CDやスクリプトから自動実行するための標準オプションが `-p`（`--print`）です。\n例: `claude -p \"Review the changes between main and this branch\"`\nこのフラグを指定すると、Claude Codeは対話プロンプト（REPL）を開かず、与えられたプロンプトに従って必要なファイル調査やコード解析、ツール実行を自律的に完了させ、最終的な回答テキストを標準出力（stdout）に出力した後に、適切な終了ステータスコード（0: 成功、非ゼロ: エラー）を返してプロセスを終了します。これにより、CIジョブがハングすることなく確実に完了します。\n\n⚠️ 引っかけポイント: バックグラウンド実行（nohup &）は成否を検証できずCIの用をなさず、仮想キーストロークや手動介入は非現実的です。",
