    "question": "【シナリオ：Claude Code の CI/CD 組み込み】\n前提: GitHub Actions ランナー上で Claude Code を実行し、リポジトリ内のコードを解析している。\nCIランナーの環境変数には、本番デプロイ用のAWS認証情報（`AWS_SECRET_ACCESS_KEY`）やデータベース本番パスワード（`DB_PASSWORD`）がシークレットとして設定されている。\n\n状況・課題:\n第三者からの悪意あるPRやコード内に含まれるインジェクション攻撃によって、Claude Code が「環境変数をすべて画面に出力するスクリプト（`env` / `printenv`）」を実行してしまい、ビルドログやPRコメントに重大な本番認証情報が平文で流出するセキュリティインシデントのリスクが発生した。\n\n問い:\nCI/CDランナー上で動作するAIエージェントによる機密環境変数の漏洩を根本的に遮断するためのアーキテクチャ設計はどれか？",
