    "question": "【シナリオ：Claude Code の CI/CD 組み込み】\n前提: 開発チームが GitHub Actions で Claude による PR 自動レビューワークフローを導入した。\n\n状況・課題:\n導入後、Claude が1つのPRに対して「変数名が少し抽象的である」「ここのコメントの言い回しを変えるべき」「好みの問題だがアロー関数にすべき」といった、本質的でない些細な指摘（Nitpick / 騒音コメント）を数十件も投稿するようになった。\n開発者が重要なバグ指摘を見落とし、レビュー疲れによってチームの生産性が著しく悪化してしまった。\n\n問い:\nAI自動コードレビューにおいて「指摘のノイズ」を最小化し、重大な不具合やセキュリティリスクに集中させるためのプロンプトおよび評価設計はどれか？",
