    "explanation": "【公式アーキテクチャ解説】\n正解は「重大度（Severity）を定義し、Critical/Highに該当する論理バグや脆弱性のみを指摘対象として些細なスタイル指摘を抑制する設計」です。\n\nAIコードレビューの導入で最も典型的な失敗が「Nitpicking（重箱の隅をつつくノイズの氾濫）」です。\n効果的なレビュープロンプト設計では：\n1. **明確なスコープ制限**: コードフォーマットやインデント等のスタイルはPrettier/ESLintに任せ、Claudeには担当させない。\n2. **Severity（重大度）基準の導入**: 「重大な論理バグ」「SQLインジェクション等のセキュリティ脆弱性」「明確なメモリリークやN+1クエリ」のみを `[Critical]` / `[High]` として報告させ、主観的な好み（Nit）は明示的に出力禁止とする。\n3. **Actionableな修正案の提示**: 指摘箇所に対して具体的な修正コード例（GitHub Suggestion形式）を添えさせる。\nこれにより、開発者の信頼とレビュー速度が劇的に向上します。\n\n⚠️ 引っかけポイント: 全自動承認はAI導入の意味がなく、無差別リジェクトや意味不明な記号投稿は開発を崩壊させます。",
