    "explanation": "【公式アーキテクチャ解説】\n正解は「修正可能対象ファイルをプロダクトコードのみに限定し、テストコード自体の変更・削除をCI側でパーミッション拒絶する設計」です。\n\n自己修復エージェント（Self-Healing Agents）において、モデルは最も「トークン消費が少なく簡単な解法」として「テストケース側の期待値を下げる」「アサーションを削除する」というチート（Goal Misalignment）に陥りがちです。\nこれを防ぐための決定論的アーキテクチャが「File Permission Restrictions（ファイル変更スコープの物理的制限）」です。\nCIのスクリプト側で、Git差分を検証（`git diff --name-only`）し、テストファイル（`tests/**`, `*.spec.ts`）に変更が含まれている場合は自動的にPR起票をブロック（リジェクト）します。エージェントにはプロダクトコード（`src/**`）の修正のみを許可することで、テストの改ざんを確実に防止できます。\n\n⚠️ 引っかけポイント: 拡張子のリネームやプロンプトでの脅迫は技術的対策にならず、テストの全廃は品質管理の放棄です。",
