    "explanation": "【公式アーキテクチャ解説】\n正解は「CLAUDE.mdにConventional Commitsの命名規則と具体例を明記し、Git commit-msgフックで正規表現バリデーションを行う構成」です。\n\nコーディングやコミット規約の徹底には「プロンプト指示（CLAUDE.md）」と「決定論的ゲートキーパー（Git Hook）」の組み合わせが最も堅牢です。\n1. `CLAUDE.md` 内に「コミットメッセージは必ず `feat:`, `fix:`, `docs:`, `refactor:` で開始し、命令形で書くこと」と具体例（Few-shot）を定義してモデルの初期出力をガイドします。\n2. さらに、Gitの `commit-msg` フックで正規表現（例: `^(feat|fix|docs|style|refactor|test|chore)(\\(.+\\))?: .+`）を検証し、違反している場合はコミット自体をブロックしてエラーメッセージをClaudeに返します。Claudeはそのエラーを見て規約に沿ったメッセージで再試行します。\n\n⚠️ 引っかけポイント: 生年月日の強制やSlackへの代替は標準規約（Conventional Commits）と無関係であり、絵文字のみへの統一はセマンティックバージョニングを破壊します。",
