      "巨大なPRはレビューを一切行わずに、CI上で無条件に自動マージして本番環境へ即日デプロイする設計。",
      "差分テキストをすべて削除し、ファイルの更新タイムスタンプの新しい順に上位3ファイルだけをレビューする設計。",
      "10万行の差分をすべて1文字ずつBase64エンコードし、文字数を半分に縮小してから投入する設計。"
