    "explanation": "【公式アーキテクチャ解説】\n正解は「差分をモジュールやディレクトリ単位のファイルチャンクに分割し、並列または順次でレビューして最後に統合要約する設計」です。\n\n大規模な差分（Large Pull Requests）に対するAIレビューのベストプラクティスは「Diff Chunking & Map-Reduce（差分の分割と集約）」です。\n1. CIスクリプトで `git diff` を解析し、論理的なグループ（例: パッケージ単位、ディレクトリ単位、またはファイル単位）に分割（Chunking）します。\n2. 各チャンクに対してClaudeを並列または順次に呼び出し、ローカルなバグや脆弱性を詳細にレビューさせます。\n3. 全チャンクのレビュー結果が出揃った後、軽量モデル（Haiku等）を用いて「全体サマリー（影響範囲、総合判定）」を取りまとめてPRの先頭コメントに投稿します。\nこれにより、コンテキスト上限を回避しつつ、見落としのない深いレビューが可能になります。\n\n⚠️ 引っかけポイント: 無条件マージは品質管理の完全な放棄であり、タイムスタンプによる適当な間引きは重要変更の見落としに直結します。",
    "officialRef": "Anthropic Certified Architect Guide: Large Diff Chunking & Map-Reduce Review"
