    "explanation": "【公式アーキテクチャ解説】\n正解は「指摘採用率（Suggestion Acceptance Rate）、PR作成からマージまでのリードタイム、リリース後のバグ流出率の推移」です。\n\n開発者支援AIツール（Developer Productivity AI）のROIおよび有効性を定量評価する業界標準メトリクスです：\n1. **指摘採用率（Acceptance Rate）**: AIが提示した改善案やSuggestionのうち、開発者が実際にコミットとして取り込んだ割合（高いほど有益な指摘）。\n2. **PRリードタイム（Cycle Time / Time to Merge）**: PR起票からレビュー完了・マージまでの時間の短縮度合い。\n3. **品質メトリクス（Escaped Defect Rate）**: レビューを通過して本番環境へ流出してしまった不具合数の変化。\nこれらを追跡・ダッシュボード化することで、プロンプトの改善効果やビジネスROIを客観的に証明できます。\n\n⚠️ 引っかけポイント: コメント文字数や電力量は価値指標にならず、スタンプの感情測定やサイコロは無意味です。",
