    "explanation": "【公式エンタープライズ解説】\n正解は「社内ネットワークの出入り口にDLPプロキシを配置し、社内特許DBの未公開化合物ハッシュと照合して該当入力を即時遮断する設計」です。\n\n製薬・半導体等のコア知財（IP）を扱うエンタープライズにおけるDLP（Data Loss Prevention: 情報漏洩防止）アーキテクチャです。\n全社AIゲートウェイの手前（またはエンドポイントエージェント）にDLP検査エンジンを配置：\n1. 入力プロンプト内に化学構造式（SMILES, InChI）や特定のプロジェクトコードネームが含まれているかを検知。\n2. 社内の未公開特許データベースの識別子や指紋（Fingerprint）と照合。\n3. 未出願化合物と一致した場合、リクエストを即座にブロックし、「未出願の化合物情報が含まれているため送信できません。特許出願完了後に利用するか、オンプレミスの閉域計算基盤を使用してください」とユーザーに安全を促します。\n\n⚠️ 引っかけポイント: 高圧電流フェンス等の極端な拘束は人権侵害であり、特許の無条件放棄は企業価値を破壊します。",
    "officialRef": "Anthropic Certified Architect Professional: IP Protection, DLP & Chemical Structure Guardrails"
