    "difficulty": "超難問",
    "type": "single",
    "question": "【シナリオ：LLM評価・MLOpsパイプライン】\n前提: 全社で本番稼働する200以上のClaudeプロンプトやモデルの品質を自動測定するため、「LLM-as-a-Judge（LLMを審査員とする自動評価システム）」パイプラインを構築している。\n評価手法として、「2つの回答（モデルA vs モデルB）を並べて勝敗を判定させるペアワイズ評価（Pairwise Comparison）」と、「単一の回答に対して絶対基準でスコア（1〜5点）を付けさせる直接採点（Direct Scoring）」の2つが検討されている。\n\n状況・課題:\n微細なプロンプトの改善差分（どちらの回答がより簡潔で事実に基づいているか）を高い感度で検出したい。\n\n問い:\nモデル間の微細な品質差を最も高感度・高精度に検出し、人間の好みの評価と最も高い相関を示すLLM評価アプローチはどれか？",
