    "explanation": "【公式エンタープライズ解説】\n正解は「2つの回答を左右に並べて評価基準に従って優劣を判定させるペアワイズ比較（Pairwise Comparison）の採用」です。\n\nLLM-as-a-Judgeにおける学術的・実務的な確立された知見です。\n絶対評価（Direct Scoring: 1〜5点評価）は、モデルの「中央値バイアス（何でも3点をつけてしまう）」や「採点基準のドリフト」の影響を受けやすく、微細な品質差を検出しにくい欠点があります。\n一方、2つの回答（AとB）を提示して「どちらがユーザーの要求を満たしているか」を比較判定させる「ペアワイズ比較（Pairwise Comparison）」は：\n1. 人間の専門家による評価（Human Preferences / LMSYS Chatbot Arena等）と極めて高い相関を示す。\n2. 微細なニュアンスの違いや論理の優劣を識別する感度（Sensitivity）が圧倒的に高い。\nこのため、モデルマイグレーションやプロンプト最適化のベンチマークにおいてデファクトスタンダードとなっています。\n\n⚠️ 引っかけポイント: 直感採点は分散が大きすぎて統計的信頼性がなく、単語カウントやジャンケンは評価になりません。",
