    "question": "【シナリオ：LLM評価・MLOpsパイプライン】\n前提: CI/CDパイプラインにおいて、GitHubのプルリクエスト（PR）作成時に、プロンプトの変更やモデルマイナー更新に対する自動リグレッションテストが実行される。\n\n状況・課題:\n「サイレントリグレッション（Silent Regression）」が発生した。\n全体の平均スコアは「85点 ➜ 86点」へとわずかに上昇していたためCIがパスしてマージされたが、実は「特定の最重要セキュリティチェック（SQLインジェクション検知）」の正答率だけが 100% から 40% へと壊滅的に暴落していることを見落としていた。\n\n問い:\n全体平均スコアの影に隠れた特定重要カテゴリのサイレントリグレッションを確実に検知・ブロックするためのCIゲート設計はどれか？",
