    "explanation": "【公式エンタープライズ解説】\n正解は「全体平均スコアだけでなく、カテゴリ別・スライス別の合格ライン（ハードゲート）を設定し、1つでも下回ればマージをブロックする設計」です。\n\nLLMの評価における最重要の罠「The Flaw of Averages（平均の罠）」への対抗策です。\n全体平均スコア（Aggregate Score）だけを指標にしていると、あるカテゴリでの改善が、別の重要カテゴリでの致命的な悪化（デグレ）を覆い隠してしまいます。\nCI/CDゲートのベストプラクティスは「Sliced Evaluation & Hard Gates（スライス評価とハードゲート）」です：\n- セキュリティカテゴリ: 合格基準 **100%必須**（1件でも落ちたら即CI失敗）\n- 業務ロジックカテゴリ: 合格基準 95%以上\n- 文章トーンカテゴリ: 全体平均 85%以上\nこのように、重要カテゴリごとに独立した許容しきい値を設定し、1つでも違反した場合はPRのマージを自動で遮断します。\n\n⚠️ 引っかけポイント: 全体平均のみに依存するCI設計はサイレントリグレッションを垂れ流す典型的なアンチパターンです。",
