    "explanation": "【公式エンタープライズ解説】\n正解は「カテゴリカル判定にはCohen's Kappa（カッパ係数）、順位・スコア判定にはSpearmanの順位相関係数を算出して提示する設計」です。\n\nLLM評価システムのバリデーション（統計的妥当性検証）における必須指標です：\n1. **Cohen's Kappa（コーエンのカッパ係数）**:\n   Pass/Fail や勝敗判定（A win / B win / Tie）などのカテゴリカルデータにおいて、偶然の一致（Chance Agreement）を除外した上で、人間とAIの一致度を測定（0.6以上で良好、0.8以上で極めて高い一致）。\n2. **Spearman's Rank Correlation（スピアマンの順位相関係数）** / **Pearson's r**:\n   1〜5点のリッカート尺度やランキングスコアにおいて、人間の評価順位とAIの評価順位の相関を測定。\nこれらの統計的検証レポートを監査部門に提示することで、LLM-as-a-Judgeの客観的証拠能力が公認されます。\n\n⚠️ 引っかけポイント: 体重の比較や合計金額、感情的な反論は統計科学の観点から完全なナンセンスです。",
