    "explanation": "【公式エンタープライズ解説】\n正解は「入力段階でBedrock Guardrailsや軽量分類モデルによる事前検証・PIIマスキングを行い、不適合リクエストをClaude到達前に高速遮断する構成」です。\n\nLLMセキュリティにおけるベストプラクティスは、LLM自身に安全性判定を丸投げするのではなく、「ゲートウェイ段階での専用セーフティレイヤー」を構築することです。\nAmazon Bedrock Guardrails（またはNeMo Guardrails、Llama Guardなどの特化型軽量モデル）を活用することで：\n1. コンテンツフィルター（ヘイト・暴力・不適切表現）\n2. 拒否トピック（Denied Topics）の判定\n3. センシティブ情報（PII）の検出とインラインマスキング\n4. プロンプト攻撃（Prompt Attack）の検出\nをClaudeへの推論リクエスト前に極小レイテンシかつ低コストで実行し、有害なリクエストを事前に弾いて無駄なLLM課金を防止できます。\n\n⚠️ 引っかけポイント: クライアント側JS検証はバイパスが容易であり、Opusへのプロンプト判定頼みはコスト高・遅延大・インジェクション耐性の低さからアンチパターンです。",
