    "explanation": "【公式エンタープライズ解説】\n正解は「W3C Trace Contextを全サービスで伝播し、TTFT・TPOT・プロンプト/完了トークン数をスパン属性として記録するOpenTelemetry計装」です。\n\nLLMを含む現代の分散トレーシング（Observability）の標準は OpenTelemetry（OTel）と W3C Trace Context です。\nHTTPヘッダー（`traceparent`）を介してリクエストIDとスパンIDを全マイクロサービス間で透過的に引き継ぐことで、単一のリクエストが各コンポーネントを通過する所要時間をウォーターフォールチャートで一目で特定できます。\nさらに、LLM呼び出しスパンには以下のOpenTelemetry GenAI Semantic Conventions属性を記録するのが必須です：\n- `gen_ai.usage.input_tokens` / `output_tokens`\n- `llm.time_to_first_token`（TTFT: プロンプト処理・推論開始遅延）\n- `llm.time_per_output_token`（TPOT: 1トークンごとの生成速度）\nこれにより、ベクトル検索の遅延なのか、ClaudeのTTFT遅延なのか、出力トークン過多による生成時間なのかを瞬時に判別できます。\n\n⚠️ 引っかけポイント: pingはネットワーク疎通しか測れず、サーバー増強はLLM外部APIの遅延には無意味です。",
