    "explanation": "【公式・Preporato詳細解説】\n正解は「C」です。\n\n名前付きのセッションを再開すると会話の履歴が正確に復元され、それがシフトの引き継ぎに必要なことです。フォークは同じ起点から独立したブランチを作るため、別の仮説は本線に書き戻すことなく分岐できます。選択肢Bはツールの履歴を捨て、分離が必要な作業に再開を使っています。選択肢Aは2つを逆にしています。引き継ぎにフォークを使うと誰も統合しない2つ目のブランチができ、仮説に新しいセ���ションを使うと共有の起点が失われます。選択肢Dはプロセスが決して終了しないことに頼っており、数日にわたるケースには脆い前提です。",
