    "difficulty": "超難問",
    "type": "single",
    "question": "【Preporato厳選 CCA-F実戦シナリオ 第5問】\n物流会社のエージェントは、トラックが故障したときにルートを再計画します。エージェントループ（メッセージを送り、Claude が要求したツールを実行し、結果を送り返すことを繰り返す）は、ルーティングのツール、ドライバーへの通知のツール、車両データベースを呼び出します。本番環境では、ドライバーに通知する前に止まってしまうことも、計画が確定した後もルーティングのツールを呼び出し続けることもあります。ループは、続行と停止をどのように判断すべきですか。",
