      "各ターンの最後に計画が完了したかをモデル自身に確認し、モデルがテキストで「はい」と答えたらループ処理を即座に停止する。",
      "アシスタントのテキストに「ルート確定」のような語句が含まれたら停止し、予備の安全策として反復回数の上限を8回に固定する。",
