    "explanation": "【公式・Preporato詳細解説】\n正解は「D」です。\n\nMessages API はすべての応答で決定論的な \\`stop_reason\\` を返し、それがループの制御のためのサポートされたシグナルです。\\`tool_use\\` はツールを実行して続行すること、\\`end_turn\\` はモデルが終えたこと、\\`max_tokens\\` は出力が途中で切れて続きの処理が必要なことを意味します。選択肢Cは自由形式のテキストを解析しており、だからこそドライバーに通知されないことがあり（作業の途中でその語句が現れる）、ループが動き続けることもあります（その語句が現れない）。選択肢Aは平均で上限を決めるため、長いインシデントが途中で打ち切られます。選択肢Bは自己申告を制御フローにしており、Cと同じ脆さに呼び出しが1回加わります。反復回数やトークンの予算は、ログを残す安全網としてだけ持っておきます。\n<!-- /ArticleQuiz -->\n\n<!-- InfoBox:type=\"tip\" title=\"学習のヒント\" -->\nドメイン1では、タスクに合ったアーキテクチャを選び、コンテキストを意図して渡す力���問われます。次に解く前に、[Claude Code のサブエージェントとオーケストレーションのパターン](/blog/claude-code-subagents-orchestration-patterns-cca-f)（英語）を読んでおきましょう。\n<!-- /InfoBox -->\n\n## ドメイン2: ツール設計とMCP統合（問題6〜9）\n\n<!-- ArticleQuiz certId=\"claude-certified-architect\" -->",
