    "question": "【Preporato厳選 CCA-F実戦シナリオ 第6問】\n人事チームのパイプラインは、届いた履歴書をすべて、\\`extract_candidate\\`、\\`check_duplicate\\`、\\`notify_recruiter\\` の3つのツールを定義して Claude に送っています。すべての履歴書は最初の呼び出しで構造化された候補者レコードを生成しなければなりませんが、応答の約20件に1件は、\\`extract_candidate\\` の呼び出しの代わりに文章の要約として返ってきます。これを最も確実に修正できる変更はどれですか。",
