    "explanation": "【公式・Preporato詳細解説】\n正解は「D」です。\n\nフックは、Claude Code のハーネスがライフサイクルのイベントで実行するシェルコマンドで、モデルの判断の外にあります。終了コード2を返す \\`PreToolUse\\` フックはツールの呼び出しをブロックして理由を Claude に返し、\\`PostToolUse\\` フックは実際の編集のたびにフォーマッターを実行します。選択肢Bも文章であることに変わりはなく、条件付きで読み込まれます。助言はできても、ブロックはできません。選択肢Aは遵守を改善しますが確率的なままで、それが報告されている失敗です。選択肢Cは、人間が気づいた場合にしか誤った編集を止められず、すべての変更を遅くし、\\`black\\` の実行には何の役にも立ちませ��。",
