    "explanation": "【公式・Preporato詳細解説】\n正解は「A」です。\n\n限られたレビューの予算は、誤りが集中しているところに向けたときに最も品質保証の効果を上げます。そして、監査はすでにその場所を突き止めています。層化抽出（リスクの高い出力は高い割合で、日常的な出力は低い割合でレビューする）と層ごとの誤りの追跡を組み合わせれば、レビューはプロンプトと検証のためのフィードバックのループになります。選択肢Dは、1日に500件しか処理できないチームに1日16,000件以上を回すことになります。選択肢Bは無作為のままなので、追加の労力のほとんどはリスクの低い判定に費やされます。選択肢Cは自己申告の確信度で、キャリブレーションが不十分なうえ、モデルが自信を持っている誤りを見逃します。\n<!-- /ArticleQuiz -->\n\n<!-- InfoBox:type=\"tip\" title=\"学習のヒント\" -->\nドメイン5の問題は、ほとんどの場合1つのアンチパターンが鍵になります（より大きなコンテキスト、感情によるきっかけ、自己申告の確信度、黙って返される空の結果）。修正方法を含む一覧は [CCA-F でよくある間違い](/blog/common-cca-f-exam-mistakes-to-avoid)（英語）にあります。\n<!-- /InfoBox -->",
