    "question": "【CCAR-F 弱点克服 第29問｜前回正答率: 50%】\n顧客からの問い合わせメールを解析し、後続のルーティングエンジンが直接読み取るための厳格なJSON構造（`category`, `urgency`, `department_id`）を出力するパイプラインを構築しています。現在、厳密なJSON Schemaを持つ `record_routing_decision` ツールを定義していますが、`tool_choice: {\"type\": \"auto\"}` になっているため、約5%のリクエストでツールを呼ばずに「かしこまりました、分類結果は以下の通りです…」という通常のテキスト応答が返り、下流のシステムがクラッシュしています。どう修正すべきですか。",
