      "temperatureを1.0に引き上げて多様な出力を促しつつ、下流のルーティングシステム側でパースエラーが発生するたびに最大50回まで同じAPIリクエストを単純リトライさせる。",
      "tool_choiceを {\"type\": \"tool\", \"name\": \"record_routing_decision\"} に設定し、会話的なテキスト応答を排除して定義済みJSONスキーマでのツール呼び出しを100%保証する。"
