    "explanation": "【公式アーキテクチャ解説】\n正解は「tool_choiceを {\"type\": \"tool\", \"name\": \"record_routing_decision\"} に設定し、会話的なテキスト応答を排除して定義済みJSONスキーマでのツール呼び出しを100%保証する。」です。\n\n■ `tool_choice` の3モードの厳密な使い分け:\n1. **`{\"type\": \"auto\"}`（デフォルト）**: ツールを呼ぶか通常の会話テキストを返すかをモデルが判断する（下流がツール呼び出しを必須とするパイプラインでは不適）。\n2. **`{\"type\": \"any\"}`**: 提供された複数ツールのうち**必ずどれか1つ以上**を呼び出させる（会話のみの返答を禁止し、どのツールを使うかはモデルに選ばせる場合）。\n3. **`{\"type\": \"tool\", \"name\": \"ツール名\"}`**: **指定した特定のツール（JSONスキーマ）の呼び出しを100%強制**する（単一の構造化抽出スキーマへの準拠を保証したい場合の絶対正解）。",
